const int strokesPerFrame = 1; // todo make this a float and skip fractional frames
const int strokeCandidates = 20; // pick the best stroke out of this many possible random strokes
const int strokeScoringFidelity = 20; // number of samples to test to decide which brush stroke is best


// create a shape within a unit circle about (0,0), return the weight per pixel for pixels in that shape
float Brush( vec2 pos )
{
//    return smoothstep(.5,.4,length(max(abs(pos)-vec2(0,.5),0.))); // soft oval
    return step(-.5,pos.y)*step(-.5,dot(pos,vec2(-sqrt(3./4.),-.5)))*step(-.5,dot(pos,vec2(sqrt(3./4.),-.5))); // equilateral triangle
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    vec4 data = texelFetch(iChannel1,ivec2(0,0),0);
    int stroke = int(data.a);

    fragColour = texelFetch(iChannel1,ivec2(fragCoord), 0 );

    if ( iFrame == 0 || floor(data.x) != floor(iResolution.x) )
    {
        stroke = 0;
        fragColour = vec4(.7,.66,.6,1);
    }

    for ( int i=0; i < strokesPerFrame; i++ )
    {
        float brushSize = iResolution.x*exp2(-3.-floor(float(stroke)/600.));

        float bestScore = 1e38;
        vec2 bestPos;
        float bestAngle;
        vec3 bestColour;

// THIS SECTION IS THE SAME ON EVERY PIXEL - could do it once in a different buffer in top left pixel
        // test a few random candidate positions and rotations
        for ( int j=0; j < strokeCandidates; j++ )
        {
            // compute score based on diff of pixel values
            // perhaps convert to OKLCH

            // pick a random position, rotation
            vec4 rand = hash4(coord1(uint(iFrame*strokesPerFrame+stroke)));
            vec2 strokeStart = rand.xy*iResolution.xy;
            float a = rand.z*6.283185;

            // pick a colour (just use colour of this pixel, or average of neighbours
            vec3 col = Ref(strokeStart).rgb;

            // test pixels within this area and add the difference to the score
            float score = 0.;
            for ( int k=0; k < strokeScoringFidelity; k++ )
            {
                vec2 testUVbrush = fract(quasi2*float(k));

                // rotate and scale uv
                vec2 testUVscreen = testUVbrush*cos(a)-sin(a)*vec2(1,-1)*testUVbrush.yx;
                testUVscreen *= brushSize;
                testUVscreen += strokeStart;

                // include already drawn pixels in the evaluation - so it focusses on areas which are currently bad
                vec3 artCol = mix( _Ref(testUVscreen,iChannel1,iResolution.xy).rgb, col, Brush(testUVbrush) ).rgb;
                vec3 refCol = Ref(testUVscreen).rgb;

                score += dot(abs( artCol - refCol ), vec3(.2,.7,.1));
// todo: weight with brush clipped to screen edge
// see if it avoids / favours the edge without this fix

                if ( brushSize < float(k) ) break;
            }


            // pick the one with the biggest score
            if ( score < bestScore )
            {
                bestScore = score;
                bestPos = strokeStart;
                bestAngle = a;
                bestColour = col;
            }
        }


        // draw with the brush
        {
            // rotate and scale uv
            vec2 uv = fragCoord-bestPos;
            uv /= brushSize;
            uv = uv*cos(bestAngle)+sin(bestAngle)*vec2(1,-1)*uv.yx;

            fragColour.rgb = mix(fragColour.rgb, bestColour, Brush(uv) );
        }

        stroke++;
    }

    // debug brush
    //fragColour = vec4(Brush((fragCoord*2.-iResolution.xy)/iResolution.y));

    // update data pixel
    if ( int(fragCoord.x)+int(fragCoord.y) == 0 )
    {
        fragColour.r = iResolution.x; // detect resolution changes
        fragColour.a = float(stroke);
    }
}

vec4 _Ref( vec2 fragCoord, sampler2D tex, vec2 res )
{
    float aspectRatio = (3./4.)*(res.x/res.y);
    vec2 uv = fragCoord/res.xy;
    uv = .5+(uv-.5)*vec2(aspectRatio,1.)/min(aspectRatio,1.);

    if ( abs(uv.x-.5) > .5 || abs(uv.y-.5) > .5 ) return vec4(.2);

    return pow( texture(tex,uv), vec4(2.2) );
}

#define Ref(a) _Ref(a,iChannel0,iResolution.xy)



// random hash from here: https://www.shadertoy.com/view/4dVBzz
#define M1 1597334677U     //1719413*929
#define M2 3812015801U     //140473*2467*11
#define M3 3299493293U     //467549*7057

#define F0 (1.0/float(0xffffffffU))

#define hash(n) n*(n^(n>>15))

#define coord1(p) (uint(p)*M1)
#define coord2(p) (uvec2(p).x*M1^uvec2(p).y*M2)
#define coord3(p) (uvec3(p).x*M1^uvec3(p).y*M2^uvec3(p).z*M3)

float hash1(uint n){return float(hash(n))*F0;}
vec2 hash2(uint n){return vec2(hash(n)*uvec2(0x1U,0x3fffU))*F0;}
vec3 hash3(uint n){return vec3(hash(n)*uvec3(0x1U,0x1ffU,0x3ffffU))*F0;}
vec4 hash4(uint n){return vec4(hash(n)*uvec4(0x1U,0x7fU,0x3fffU,0x1fffffU))*F0;}

// quasirandom sequences, kind of like an n-dimensional golden ratio
const vec2 quasi2 = vec2(0.7548777,0.5698403);
const vec3 quasi3 = vec3(0.8191725,0.6710436,0.5497005);
